import { INSEPARABLE_TAGS } from "../../core/constants.js";
import { Dom } from "../../core/dom/index.js";
import { pluginSystem } from "../../core/global.js";
import { Config } from "../../config.js";
/**
 * After loading the page into the editor once the focus is set
 */
Config.prototype.autofocus = false;
/**
 * Cursor position after autofocus
 */
Config.prototype.cursorAfterAutofocus = 'end';
/**
 * Save current selection on blur event
 */
Config.prototype.saveSelectionOnBlur = true;
export function focus(editor) {
    if (editor.o.saveSelectionOnBlur) {
        // A click that brings focus back places the caret itself, and Chrome
        // has already placed it when focus fires, so restoring would move it
        // back to the old selection. The saved markers are dropped instead.
        let focusByPointer = false;
        editor.e
            .on('blur', () => {
            // A press that never brought the focus back must not decide
            // what the next focus does
            focusByPointer = false;
            if (editor.isEditorMode()) {
                editor.s.save(true);
            }
        })
            .on('mousedown touchstart', () => {
            focusByPointer = !editor.editorIsActive;
        })
            .on('focus', () => {
            if (editor.isEditorMode()) {
                if (focusByPointer) {
                    editor.s.removeMarkers();
                }
                else {
                    editor.s.restore();
                }
            }
            focusByPointer = false;
        });
    }
    const focus = () => {
        editor.s.focus();
        let textNode = null;
        switch (editor.o.cursorAfterAutofocus) {
            case 'start':
                textNode = Dom.first(editor.editor, node => Dom.isText(node));
                break;
            case 'end':
                textNode = Dom.last(editor.editor, node => Dom.isText(node));
                break;
        }
        if (textNode) {
            editor.s.setCursorIn(textNode, editor.o.cursorAfterAutofocus === 'start');
        }
    };
    editor.e.on('afterInit', () => {
        if (editor.o.autofocus) {
            if (editor.defaultTimeout) {
                // A click or key in the editor during the delay has put the
                // caret where the user wants it, so autofocus leaves it there
                const userInput = 'mousedown touchstart keydown';
                const cancel = () => {
                    editor.async.clearTimeout(timeout);
                    editor.e.off(userInput, cancel);
                };
                const timeout = editor.async.setTimeout(() => {
                    editor.e.off(userInput, cancel);
                    focus();
                }, 300);
                editor.e.on(userInput, cancel);
            }
            else {
                focus();
            }
        }
    });
    editor.e.on('afterInit afterAddPlace', () => {
        editor.e
            .off(editor.editor, 'mousedown.autofocus')
            .on(editor.editor, 'mousedown.autofocus', (e) => {
            // An empty block takes the caret, but a video, say, can't hold one
            if (editor.isEditorMode() &&
                e.target &&
                Dom.isBlock(e.target) &&
                !Dom.isTag(e.target, INSEPARABLE_TAGS) &&
                !e.target.childNodes.length) {
                if (editor.editor === e.target) {
                    editor.s.focus();
                }
                else {
                    editor.s.setCursorIn(e.target);
                }
            }
        });
    });
}
pluginSystem.add('focus', focus);
